{
  "findings": [
    {
      "title": "Inconsistent number of PFS events: 230 total events vs 160 events at 70%",
      "page": 55,
      "quote": "The PA of PFS will occur when approximately 230 PFS events have been observed. ... An IA of PFS for superiority is planned when approximately 70% (160 events) of the total PFS events have been observed",
      "severity": "major"
    },
    {
      "title": "Inconsistent OS analysis thresholds: 175 vs 198 events",
      "page": 55,
      "quote": "OS will be assessed for superiority ... at either the time of PFS primary analysis or after 175 OS events have been observed, whichever is later. The OS primary analysis will occur when at least 198 OS events (~60% maturity) have been observed",
      "severity": "major"
    },
    {
      "title": "Inconsistent QTc inclusion criteria: females > males",
      "page": 60,
      "quote": "QTc ≤ 470 msec in females and ≤ 450 msec in males",
      "severity": "major"
    },
    {
      "title": "Inconsistent tumor assessment schedule: every 6 weeks vs weeks 7, 13, 19...",
      "page": 52,
      "quote": "every 6 weeks from cycle 1 day 1; (± 7 days) (at weeks 7, 13, 19, 25, 31, 37, 43, and 49)",
      "severity": "major"
    },
    {
      "title": "Inconsistent study duration: 6.5 years vs 28 days + 8 months + 5 years",
      "page": 58,
      "quote": "The total study duration is estimated to be up to 6.5 years. This includes a screening period of up to 28 days, duration of treatment for an individual subject of approximately 8 months followed by an SFU visit ... After the SFU visit, subjects enter LTFU for up to 5 years.",
      "severity": "major"
    },
    {
      "title": "Inconsistent DMC safety review schedule: 50, 100, 200 vs 330 subjects",
      "page": 54,
      "quote": "Data monitoring committee will meet to review safety after 50, 100, and 200 subjects are enrolled",
      "severity": "minor"
    },
    {
      "title": "Inconsistent crossover criteria: investigator vs BICR assessment",
      "page": 52,
      "quote": "Once subjects on the docetaxel arm are determined to have radiological progression according to RECIST v1.1 by the investigator and progressive disease is confirmed by independent central imaging review, they will be given the opportunity to crossover",
      "severity": "minor"
    },
    {
      "title": "Inconsistent treatment beyond progression criteria: BICR vs investigator",
      "page": 53,
      "quote": "Subjects that consent to treatment beyond progression ... will continue to receive investigational product after independent central confirmation of progression at the time of first progressive disease (PD).",
      "severity": "minor"
    },
    {
      "title": "Inconsistent inclusion criterion 105: prior therapy requirements",
      "page": 59,
      "quote": "Prior treatment must include a platinum-based doublet chemotherapy and checkpoint inhibitor for advanced or metastatic disease, either given as one line of therapy or as individual lines of therapy unless the subject has a medical contraindication",
      "severity": "minor"
    },
    {
      "title": "Inconsistent exclusion criterion 201: prior docetaxel in unresectable or metastatic setting",
      "page": 60,
      "quote": "Subjects have received prior docetaxel in unresectable or metastatic setting (including subjects who received prior docetaxel in first line for metastatic disease, but not including subjects who received prior docetaxel neoadjuvantly or adjuvantly and did not progress within 6 months of end of therapy).",
      "severity": "minor"
    },
    {
      "title": "Inconsistent exclusion criterion 204: active brain metastases definition",
      "page": 60,
      "quote": "Active brain metastases are defined as: Untreated brain lesions (new or progressing) and/or symptomatic brain lesions (symptoms as determined by the investigator), present at the time of study entry.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent exclusion criterion 208: hepatitis B testing requirements",
      "page": 60,
      "quote": "Negative HepBsAg with a positive for hepatitis B core antibody (Hepatitis B core antibody testing is not required for screening, however if this is done and is positive, then hepatitis B surface antibody [Anti-HBs] testing is necessary.",
      "severity": "minor"
    }
  ]
}
